/**
 * qr-parse.js
 *
 * Pure parsing helper for QR / pasted URLs on the sender's scan step.
 * Lives in its own module so it can be unit-tested without bringing in
 * send.html's WebRTC / camera / connect machinery.
 *
 * parseSendInvite(data, currentOrigin) returns one of:
 *   { ok: true,  roomId: 'ABC123', secret: 'xxxx...' }
 *   { ok: false, reason: 'foreign-origin' | 'no-room' | 'secret-missing' }
 *
 * Foreign-origin defense: legitimate QRs are generated by receive.html
 * as `${window.location.origin}/send/...#...`, so URL.origin always
 * matches the page that scans them. A phishing QR encoding a foreign
 * origin would, without this check, silently make the sender join a
 * room on THIS server (which the attacker also created), bypassing the
 * visible-URL signal that something is off. We only reject on a real
 * cross-origin URL; bare relative paths (manual entry) fall through.
 *
 * Exposed as window.QrParse.
 * Generated with the help of Claude Code.
 */
(function () {
    'use strict';

    // Room ID: 6 chars from server-helpers.ROOM_ID_CHARS, case-insensitive.
    // Secret: base64url of 16 random bytes ⇒ 22 chars from [A-Za-z0-9_-];
    // we allow 20..32 to tolerate future tweaks. Bounded length stops a
    // hostile QR from smuggling CR/LF or oversized junk into the
    // X-Room-Secret header on the network call.
    const PATH_RE = /\/send\/([A-Z0-9]{6})(?:#([A-Za-z0-9_-]{20,32}))?$/i;

    function parseSendInvite(data, currentOrigin) {
        if (typeof data !== 'string' || data.length === 0) {
            return { ok: false, reason: 'no-room' };
        }
        try {
            const u = new URL(data);
            if (u.origin !== currentOrigin) {
                return { ok: false, reason: 'foreign-origin', foreignOrigin: u.origin };
            }
        } catch (_) {
            /* not a URL, may be a relative path - fall through */
        }
        const m = data.match(PATH_RE);
        if (!m) return { ok: false, reason: 'no-room' };
        const roomId = m[1].toUpperCase();
        const secret = m[2] || null;
        if (!secret) return { ok: false, reason: 'secret-missing', roomId };
        return { ok: true, roomId, secret };
    }

    window.QrParse = { parseSendInvite };
})();
